begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('95000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email) select pg_temp.i(n),'owner-review-'||n||'@example.invalid' from generate_series(11,12)n;
insert into auth.sessions(id,user_id) select pg_temp.i(n),pg_temp.i(n) from generate_series(11,12)n;
insert into public.organizations(id,name) values(pg_temp.i(1),'TEST questions');
insert into public.branches(id,organization_id,name,code) values(pg_temp.i(101),pg_temp.i(1),'TEST branch','T1');
insert into public.staff_memberships(organization_id,user_id,branch_id,role,name) values(pg_temp.i(1),pg_temp.i(11),null,'owner','Owner'),(pg_temp.i(1),pg_temp.i(12),pg_temp.i(101),'cashier','Cashier');
insert into public.products(id,organization_id,name,sku,base_unit,cost_pending,owner_review) values(pg_temp.i(301),pg_temp.i(1),'TEST question','TEST-Q','piece',true,'{"questions":["TEST confirm unit and actual cost"],"categories":["Generic unit","Cost unconfirmed"],"source":"TEST evidence","queuedAt":"2026-11-03"}');
insert into public.product_units(id,organization_id,product_id,name,factor) values(pg_temp.i(401),pg_temp.i(1),pg_temp.i(301),'Sealed item / piece',1);
insert into public.unit_prices values(pg_temp.i(1),pg_temp.i(401),1,100,0,now());
create function pg_temp.login(n integer) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(n),'session_id',pg_temp.i(n),'role','authenticated','is_anonymous',false)::text,true)$$;
create function pg_temp.ctx() returns jsonb language sql as $$select jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'productId',pg_temp.i(301))$$;
create function pg_temp.review() returns jsonb language sql as $$select public.agri_command('snapshot',pg_temp.ctx())->'products'->0->'ownerReview'$$;
create temporary table saved(data jsonb);grant all on saved to authenticated;
set local role authenticated;select pg_temp.login(11);
select is(pg_temp.review()->'complete','false'::jsonb,'Queued uncertainty is pending');
select is(pg_temp.review()->'questions'->>0,'TEST confirm unit and actual cost','Snapshot preserves exact owner question');
insert into saved select pg_temp.ctx()||jsonb_build_object('requestId',pg_temp.i(701),'expectedReviewRevision',pg_temp.review()->>'revision','note','TEST package and actual invoice checked','confirmed',true);
select throws_ok($$select public.agri_command('complete_product_review',(select data from saved)||'{"confirmed":false}')$$,'P0001','Confirm every question and enter the owner answer or evidence','Explicit owner confirmation required');
select throws_ok($$select public.agri_command('complete_product_review',(select data from saved))$$,'P0001','Resolve the missing unit, price, cost and unposted stock before completing this review','Unknown costs cannot be dismissed');
select pg_temp.login(12);
select throws_ok($$select public.agri_command('complete_product_review',(select data from saved))$$,'42501','Only the owner can complete inventory reviews','Cashier cannot complete reviews');
select throws_ok($$update public.products set owner_review=null where id=pg_temp.i(301)$$,'42501',null,'Direct metadata writes are denied');
reset role;
update public.products set cost_pending=false where id=pg_temp.i(301);
set local role authenticated;select pg_temp.login(11);
select throws_ok($$select public.agri_command('complete_product_review',(select data from saved))$$,'P0001','This product changed. Refresh and check its questions again','Changed evidence rejects stale completion');
update saved set data=data||jsonb_build_object('expectedReviewRevision',pg_temp.review()->>'revision');
select lives_ok($$select public.agri_command('complete_product_review',(select data from saved))$$,'Owner answer can be saved after required setup is resolved');
select is(pg_temp.review()->'complete','true'::jsonb,'Completed status persists in database snapshot');
select is(pg_temp.review()->>'note','TEST package and actual invoice checked','Owner answer persists');
select is(public.agri_command('complete_product_review',(select data from saved))->'duplicate','true'::jsonb,'Lost-response retry is idempotent');
select throws_ok($$select public.agri_command('complete_product_review',(select data from saved)||'{"note":"TEST different answer"}')$$,'P0001','This request reference belongs to a different review','Retry cannot silently change owner answer');
select throws_ok($$select public.agri_command('complete_product_review',(select data from saved)||jsonb_build_object('requestId',pg_temp.i(702)))$$,'P0001','This product is already reviewed','A fresh request cannot repeat a completed review');
select lives_ok($$select public.agri_command('review_product_price',pg_temp.ctx()||jsonb_build_object('requestId',pg_temp.i(703),'unitId',pg_temp.i(401),'expectedPriceVersion',1,'price',120,'cost',80,'reason','TEST later verified price','confirmed',true))$$,'Later price correction remains an independent action');
select is(pg_temp.review()->'complete','false'::jsonb,'Later price correction reopens the owner review');
select is(pg_temp.review()->>'note','TEST package and actual invoice checked','Previous answer remains available when reopened');
reset role;
select is((select count(*)::integer from public.stock_control_events where action='complete_product_review'),1,'One durable review event');
select is((select count(*)::integer from public.audit_events where action='complete_product_review'),1,'One owner audit trail');
select is((select count(*)::integer from public.inventory_movements),0,'Review does not post stock');
select is((select count(*)::integer from public.sales),0,'Review does not create sales');
select is((select count(*)::integer from public.payments),0,'Review does not move cash');
select is((select price from public.unit_prices where unit_id=pg_temp.i(401) and version=1),100::bigint,'Historical prices unchanged');
select * from finish();rollback;
